//! 📐️ STEP exchange headers, typed argument ownership and entity references.
use super::{StepSnapshot,StepHeader,StepFileDescription,StepFileName,StepFileSchema,StepEntity,StepComplexType,StepValue};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,FloatColumn,insert_ieee754,read_binary64,ieee754_is_null,validate_ieee754_row,reconstruct_text},*}};
use std::collections::{BTreeMap,BTreeSet};
const REAL:&[FloatColumn]=&[FloatColumn::Binary64(3)];
fn native_text(text:&str,bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),String>{bound.repeated(text.len(),16)?;bound.add(64)}
fn native_arguments(roots:&[StepValue],bound:&mut artifact::NativeEncodingBound<'_,'_>)->Result<(),String>{bound.check_rows(roots.len())?;bound.repeated(roots.len(),std::mem::size_of::<&StepValue>())?;let mut pending=Vec::with_capacity(roots.len());for(index,root)in roots.iter().enumerate(){pending.push(root);if index%256==0{bound.checkpoint()?;}}let mut count=0usize;while let Some(value)=pending.pop(){count=count.checked_add(1).ok_or("STEP native argument count overflow")?;bound.check_rows(count)?;bound.add(128)?;match value{StepValue::String(value)|StepValue::Enum(value)=>native_text(value,bound)?,StepValue::Real(value)=>{if !value.is_finite(){return Err("STEP native Part21 syntax cannot encode non-finite real words; owned SQLite retains them".into());}bound.add(768)?;},StepValue::Aggregate(items)=>{bound.check_rows(pending.len().checked_add(items.len()).ok_or("STEP native argument frontier overflow")?)?;bound.repeated(items.len(),std::mem::size_of::<&StepValue>())?;for(index,item)in items.iter().enumerate(){pending.push(item);if index%256==0{bound.checkpoint()?;}}},StepValue::TypedValue{type_name,value}=>{native_text(type_name,bound)?;pending.push(value);},_=>{}}}Ok(())}
/// 🪜️ Borrowed AP214 facts shared by the six owned conformance classes.
pub struct ConformanceFacts<'a>{pub file_schema:bool,pub product_chain:bool,pub violations:Vec<(u64,&'a str,u8)>}
/// 🔎️ Scans retained STEP type names without materializing a Part-21 graph.
pub fn conformance_facts<'a>(snapshot:&'a StepSnapshot,max_rung:u8,control:&mut SqliteSnapshotControl<'_>)->Result<ConformanceFacts<'a>,String>{
    control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;
    let mut total=snapshot.header.file_schema.schemas.len();
    for(index,entity)in snapshot.entities.iter().enumerate(){total=total.checked_add(entity.complex.len()).and_then(|n|n.checked_add(1)).ok_or("STEP conformance count overflow")?;control.check_rows(total)?;if index%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,index,snapshot.entities.len())?;}}
    control.check_rows(total)?;
    let mut facts=ConformanceFacts{file_schema:false,product_chain:false,violations:Vec::new()};let mut seen=[false;3];let mut count=0usize;let mut diagnostic_bytes=512usize;
    for name in &snapshot.header.file_schema.schemas{facts.file_schema|=name.eq_ignore_ascii_case("AUTOMOTIVE_DESIGN");count+=1;if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,total)?;}}
    for entity in &snapshot.entities{for name in std::iter::once(entity.name.as_str()).chain(entity.complex.iter().map(|part|part.name.as_str())){
        seen[0]|=name.eq_ignore_ascii_case("PRODUCT");seen[1]|=name.eq_ignore_ascii_case("PRODUCT_DEFINITION_FORMATION")||name.eq_ignore_ascii_case("PRODUCT_DEFINITION_FORMATION_WITH_SPECIFIED_SOURCE");seen[2]|=name.eq_ignore_ascii_case("PRODUCT_DEFINITION")||name.eq_ignore_ascii_case("PRODUCT_DEFINITION_WITH_ASSOCIATED_DOCUMENTS");
        let rung=if name.get(name.len().saturating_sub(20)..).is_some_and(|suffix|suffix.eq_ignore_ascii_case("SHAPE_REPRESENTATION")){Some(if name.eq_ignore_ascii_case("GEOMETRICALLY_BOUNDED_SURFACE_SHAPE_REPRESENTATION"){3}else if name.eq_ignore_ascii_case("MANIFOLD_SURFACE_SHAPE_REPRESENTATION"){4}else if name.eq_ignore_ascii_case("FACETED_BREP_SHAPE_REPRESENTATION"){5}else if name.eq_ignore_ascii_case("ADVANCED_BREP_SHAPE_REPRESENTATION"){6}else{2})}else{None};
        if let Some(rung)=rung.filter(|rung|*rung>max_rung){diagnostic_bytes=diagnostic_bytes.checked_add(name.len()).and_then(|n|n.checked_add(200)).ok_or("STEP diagnostic size overflow")?;control.check_value_bytes(diagnostic_bytes)?;if name.len()>65536{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,total)?;}facts.violations.push((entity.id,name,rung));}
        count+=1;if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,total)?;}
    }}facts.product_chain=seen.into_iter().all(|value|value);control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,total)?;Ok(facts)
}
fn number(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|e|e.to_string())}
fn identity(row:&SqliteRow,columns:usize)->Result<(),String>{if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns{Err("invalid STEP entity identity or columns".into())}else{Ok(())}}
fn unsigned(text:&str)->Result<u64,String>{let value=text.parse::<u64>().map_err(|e|e.to_string())?;if value.to_string()!=text{Err("STEP unsigned field must be canonical decimal text".into())}else{Ok(value)}}
fn null(row:&SqliteRow,index:usize)->Result<(),String>{if row.values.get(index)==Some(&SqliteValue::Null){Ok(())}else{Err("unexpected STEP value variant field".into())}}
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<(),String>{*count=count.checked_add(1).ok_or("STEP traversal count overflow")?;if *count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;}Ok(())}
enum Owner<'a>{Argument(Option<i64>,Option<i64>,usize),Aggregate(i64,usize),Typed(i64,&'a str)}
fn project_value(value:&StepValue,owner:Owner<'_>,entities:&BTreeMap<u64,i64>,projection:&mut Projection<'_,'_>)->Result<(),String>{
    let mut pending=vec![(value,owner)];
    while let Some((value,owner))=pending.pop(){projection.checkpoint()?;let mut cells=[Cell::Null;7];let reference;
        cells[0]=Cell::Text(match value{StepValue::Unset=>"unset",StepValue::Derived=>"derived",StepValue::Integer(_)=>"integer",StepValue::Real(_)=>"real",StepValue::String(_)=>"string",StepValue::Enum(_)=>"enum",StepValue::Reference(_)=>"reference",StepValue::Aggregate(_)=>"aggregate",StepValue::TypedValue{..}=>"typedValue"});
        match value{StepValue::Integer(v)=>cells[1]=Cell::Integer(*v),StepValue::Real(v)=>cells[2]=Cell::Real(*v),StepValue::String(v)=>cells[3]=Cell::Text(v),StepValue::Enum(v)=>cells[4]=Cell::Text(v),StepValue::Reference(v)=>{reference=v.to_string();cells[5]=Cell::Text(&reference);cells[6]=Cell::Integer(*entities.get(v).ok_or("dangling STEP entity reference")?);},_=>{}}
        let id=insert_ieee754(projection,"step_value",&cells,REAL)?;
        match owner{Owner::Argument(entity,complex,ordinal)=>{projection.insert("step_argument",&[entity.map_or(Cell::Null,Cell::Integer),complex.map_or(Cell::Null,Cell::Integer),Cell::Integer(number(ordinal)?),Cell::Integer(id)])?;},Owner::Aggregate(parent,ordinal)=>{projection.insert("step_aggregate_element",&[Cell::Integer(parent),Cell::Integer(number(ordinal)?),Cell::Integer(id)])?;},Owner::Typed(parent,name)=>{projection.insert("step_typed_value",&[Cell::Integer(parent),Cell::Text(name),Cell::Integer(id)])?;}}
        match value{StepValue::Aggregate(values)=>{projection.check_rows(pending.len().checked_add(values.len()).ok_or("STEP pending value count overflow")?)?;for(ordinal,value)in values.iter().enumerate().rev(){pending.push((value,Owner::Aggregate(id,ordinal)));if ordinal%256==0{projection.checkpoint()?;}}},StepValue::TypedValue{type_name,value}=>pending.push((value,Owner::Typed(id,type_name))),_=>{}}
    }Ok(())
}
fn ordered<'a>(mut rows:Vec<&'a SqliteRow>,ordinal:usize,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<&'a SqliteRow>,String>{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;rows.sort_by_key(|row|row.integer(ordinal).unwrap_or(i64::MIN));for(index,row)in rows.iter().enumerate(){if row.integer(ordinal)?!=number(index)?{return Err("STEP relationship ordinals must be contiguous and unique".into());}checkpoint(control,count)?;}Ok(rows)}
fn group<'a>(database:&'a SqliteDatabase,table:&str,owner:usize,ordinal:usize,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();for row in &database.table(table)?.rows{groups.entry(row.integer(owner)?).or_default().push(row);checkpoint(control,count)?;}for rows in groups.values_mut(){*rows=ordered(std::mem::take(rows),ordinal,control,count)?;}Ok(groups)}
fn header_list(database:&SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<String>,String>{let rows=ordered(database.table(table)?.rows.iter().collect(),2,control,count)?;let mut result=Vec::with_capacity(rows.len());for row in rows{if row.integer(1)?!=1{return Err("STEP header list belongs to another header".into());}result.push(reconstruct_text(control,row.text(3)?)?);}Ok(result)}
fn take_arguments(arguments:&mut BTreeMap<(bool,i64),Vec<&SqliteRow>>,values:&mut BTreeMap<i64,StepValue>,owner:(bool,i64),control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<StepValue>,String>{let rows=arguments.remove(&owner).unwrap_or_default();let mut result=Vec::with_capacity(rows.len());for row in rows{result.push(values.remove(&row.integer(4)?).ok_or("missing STEP argument value")?);checkpoint(control,count)?;}Ok(result)}
fn restore_values(database:&SqliteDatabase,entities:&BTreeMap<i64,u64>,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<BTreeMap<i64,StepValue>,String>{
    let mut values=BTreeMap::new();for row in &database.table("step_value")?.rows{values.insert(row.rowid,row);checkpoint(control,count)?;}
    let mut aggregates=group(database,"step_aggregate_element",1,2,control,count)?;let mut wrappers=BTreeMap::new();
    for row in &database.table("step_typed_value")?.rows{let owner=row.integer(1)?;if values.get(&owner).ok_or("dangling STEP typed wrapper")?.text(1)?!="typedValue"||wrappers.insert(owner,(row.text(2)?,row.integer(3)?)).is_some(){return Err("invalid STEP typed wrapper owner".into());}checkpoint(control,count)?;}
    for parent in aggregates.keys(){if values.get(parent).ok_or("dangling STEP aggregate")?.text(1)?!="aggregate"{return Err("STEP aggregate relationship has wrong parent kind".into());}checkpoint(control,count)?;}
    let mut seen=BTreeSet::new();let mut complete=BTreeMap::new();
    for argument in &database.table("step_argument")?.rows{let root=argument.integer(4)?;let mut pending=vec![(root,false)];
        while let Some((id,exit))=pending.pop(){checkpoint(control,count)?;let row=*values.get(&id).ok_or("dangling STEP value ownership edge")?;if !exit{if !seen.insert(id){return Err("cyclic or multiply owned STEP value".into());}pending.push((id,true));if let Some(rows)=aggregates.get(&id){for child in rows.iter().rev(){pending.push((child.integer(3)?,false));checkpoint(control,count)?;}}if let Some((_,child))=wrappers.get(&id){pending.push((*child,false));}continue;}
            validate_ieee754_row(row,8,REAL)?;let kind=row.text(1)?;let active=match kind{"integer"=>Some(2),"real"=>Some(3),"string"=>Some(4),"enum"=>Some(5),"reference"=>Some(6),"unset"|"derived"|"aggregate"|"typedValue"=>None,_=>return Err("unknown STEP value kind".into())};
            for index in 2..8{if Some(index)!=active&&!(kind=="reference"&&index==7){null(row,index)?;}}if kind!="real"&&!ieee754_is_null(row,3,REAL)?{return Err("inactive STEP real companions".into());}
            let value=match kind{"unset"=>StepValue::Unset,"derived"=>StepValue::Derived,"integer"=>StepValue::Integer(row.integer(2)?),"real"=>StepValue::Real(read_binary64(row,3,REAL)?),"string"=>StepValue::String(reconstruct_text(control,row.text(4)?)?),"enum"=>StepValue::Enum(reconstruct_text(control,row.text(5)?)?),"reference"=>{let value=unsigned(row.text(6)?)?;if entities.get(&row.integer(7)?)!=Some(&value){return Err("STEP reference word differs from related entity identity".into());}StepValue::Reference(value)},"aggregate"=>{let rows=aggregates.remove(&id).unwrap_or_default();let mut items=Vec::with_capacity(rows.len());for child in rows{items.push(complete.remove(&child.integer(3)?).ok_or("invalid STEP aggregate ownership")?);checkpoint(control,count)?;}StepValue::Aggregate(items)},"typedValue"=>{let(name,child)=wrappers.remove(&id).ok_or("missing STEP typed wrapper")?;StepValue::TypedValue{type_name:reconstruct_text(control,name)?,value:Box::new(complete.remove(&child).ok_or("invalid STEP typed child ownership")?)}},_=>unreachable!()};complete.insert(id,value);
        }
    }
    if seen.len()!=values.len()||!aggregates.is_empty()||!wrappers.is_empty(){return Err("unowned STEP value entity".into());}Ok(complete)
}
impl ArtifactSqliteSnapshot for StepSnapshot{
    fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=artifact::NativeEncodingBound::new(control)?;bound.add(1024)?;let h=&self.header;let n=&h.file_name;for text in [&h.file_description.implementation_level,&n.name,&n.timestamp,&n.preprocessor_version,&n.originating_system,&n.authorization]{native_text(text,&mut bound)?;}for list in [&h.file_description.description,&n.author,&n.organization,&h.file_schema.schemas]{bound.check_rows(list.len())?;for(index,text)in list.iter().enumerate(){native_text(text,&mut bound)?;if index%256==0{bound.checkpoint()?;}}}bound.check_rows(self.entities.len())?;for(index,entity)in self.entities.iter().enumerate(){bound.add(128)?;native_text(&entity.name,&mut bound)?;native_arguments(&entity.args,&mut bound)?;bound.check_rows(entity.complex.len())?;for(index,part)in entity.complex.iter().enumerate(){bound.add(128)?;native_text(&part.name,&mut bound)?;native_arguments(&part.args,&mut bound)?;if index%256==0{bound.checkpoint()?;}}if index%256==0{bound.checkpoint()?;}}bound.finish()}
    fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_os_kernel::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.step"||dialect.standard!="ap214"{return Err(String::from("owned STEP dialect differs from its semantic standard").into());}let row=database.table("step_document")?.single_row()?;if row.rowid!=1||row.text(1)?!=self.schema{return Err(String::from("owned STEP document identity differs from semantic projection").into());}let diagnostics=match dialect.subset.as_str(){"*"=>Vec::new(),"cc1"=>crate::standards::v_ap214::subsets::cc1::schema::check_cc1_conformance_controlled(self,control)?,"cc2"=>crate::standards::v_ap214::subsets::cc2::schema::check_cc2_conformance_controlled(self,control)?,"cc3"=>crate::standards::v_ap214::subsets::cc3::schema::check_cc3_conformance_controlled(self,control)?,"cc4"=>crate::standards::v_ap214::subsets::cc4::schema::check_cc4_conformance_controlled(self,control)?,"cc5"=>crate::standards::v_ap214::subsets::cc5::schema::check_cc5_conformance_controlled(self,control)?,"cc6"=>crate::standards::v_ap214::subsets::cc6::schema::check_cc6_conformance_controlled(self,control)?,_=>return Err(String::from("unknown owned STEP subset").into())};Ok(semio_framework_os_kernel::io_schema::IoOutcome{value:(),diagnostics})
    }
    const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
    fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
        let header=&self.header;let mut predicted=2usize;for length in [self.entities.len(),header.file_description.description.len(),header.file_name.author.len(),header.file_name.organization.len(),header.file_schema.schemas.len()]{predicted=predicted.checked_add(length).ok_or("STEP projected row count overflow")?;}control.check_rows(predicted.checked_add(1).ok_or("STEP metadata row count overflow")?)?;control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;
        let mut identities=BTreeMap::new();for(ordinal,entity)in self.entities.iter().enumerate(){if identities.insert(entity.id,number(ordinal+1)?).is_some(){return Err("duplicate STEP instance identifier".into());}if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,ordinal,0)?;}}
        let mut projection=Projection::new(Self::SQLITE_SCHEMA,control)?;projection.insert_key("step_document",1,&[Cell::Text(&self.schema),Cell::Integer(1)])?;let name=&header.file_name;projection.insert_key("step_header",1,&[Cell::Text(&header.file_description.implementation_level),Cell::Text(&name.name),Cell::Text(&name.timestamp),Cell::Text(&name.preprocessor_version),Cell::Text(&name.originating_system),Cell::Text(&name.authorization)])?;
        for(table,values)in [("step_description",&header.file_description.description),("step_author",&name.author),("step_organization",&name.organization),("step_schema_identifier",&header.file_schema.schemas)]{for(ordinal,value)in values.iter().enumerate(){projection.insert(table,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(value)])?;}}
        for(ordinal,entity)in self.entities.iter().enumerate(){let key=*identities.get(&entity.id).ok_or("missing STEP entity identity")?;let word=entity.id.to_string();projection.insert_key("step_entity",key,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&word),Cell::Text(&entity.name)])?;projection.check_rows(entity.args.len())?;for(ordinal,value)in entity.args.iter().enumerate(){project_value(value,Owner::Argument(Some(key),None,ordinal),&identities,&mut projection)?;}projection.check_rows(entity.complex.len())?;for(ordinal,complex)in entity.complex.iter().enumerate(){let complex_id=projection.insert("step_complex_type",&[Cell::Integer(key),Cell::Integer(number(ordinal)?),Cell::Text(&complex.name)])?;projection.check_rows(complex.args.len())?;for(ordinal,value)in complex.args.iter().enumerate(){project_value(value,Owner::Argument(None,Some(complex_id),ordinal),&identities,&mut projection)?;}}}projection.finish()
    }
    fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
        validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let mut count=0;
        for(table,columns)in [("step_document",3),("step_header",7),("step_description",4),("step_author",4),("step_organization",4),("step_schema_identifier",4),("step_entity",5),("step_complex_type",4),("step_argument",5),("step_value",10),("step_aggregate_element",4),("step_typed_value",4)]{let mut ids=BTreeSet::new();for row in &database.table(table)?.rows{identity(row,columns)?;if !ids.insert(row.rowid){return Err("duplicate STEP relational row identity".into());}checkpoint(control,&mut count)?;}}
        let document=database.table("step_document")?.single_row()?;let header=database.table("step_header")?.single_row()?;if document.rowid!=1||document.integer(2)?!=1||header.rowid!=1{return Err("invalid STEP document/header ownership".into());}
        let entity_rows=ordered(database.table("step_entity")?.rows.iter().collect(),2,control,&mut count)?;let mut entities=BTreeMap::new();let mut words=BTreeSet::new();for row in &entity_rows{let value=unsigned(row.text(3)?)?;if row.integer(1)?!=1||!words.insert(value){return Err("invalid STEP instance owner or duplicate identity".into());}entities.insert(row.rowid,value);checkpoint(control,&mut count)?;}
        let mut complex=group(database,"step_complex_type",1,2,control,&mut count)?;let mut arguments=BTreeMap::<(bool,i64),Vec<&SqliteRow>>::new();for row in &database.table("step_argument")?.rows{let owner=match(&row.values[1],&row.values[2]){(SqliteValue::Integer(id),SqliteValue::Null)=>(false,*id),(SqliteValue::Null,SqliteValue::Integer(id))=>(true,*id),_=>return Err("STEP argument must have exactly one owner".into())};arguments.entry(owner).or_default().push(row);checkpoint(control,&mut count)?;}for rows in arguments.values_mut(){*rows=ordered(std::mem::take(rows),3,control,&mut count)?;}
        let mut values=restore_values(database,&entities,control,&mut count)?;
        let mut restored=Vec::with_capacity(entity_rows.len());for row in entity_rows{let args=take_arguments(&mut arguments,&mut values,(false,row.rowid),control,&mut count)?;let mut types=Vec::new();for child in complex.remove(&row.rowid).unwrap_or_default(){types.push(StepComplexType{name:reconstruct_text(control,child.text(3)?)?,args:take_arguments(&mut arguments,&mut values,(true,child.rowid),control,&mut count)?});checkpoint(control,&mut count)?;}restored.push(StepEntity{id:*entities.get(&row.rowid).ok_or("missing STEP instance word")?,name:reconstruct_text(control,row.text(4)?)?,args,complex:types});checkpoint(control,&mut count)?;}
        if !complex.is_empty()||!arguments.is_empty()||!values.is_empty(){return Err("unowned STEP entity relationship".into());}
        let result=Self{schema:reconstruct_text(control,document.text(1)?)?,header:StepHeader{file_description:StepFileDescription{description:header_list(database,"step_description",control,&mut count)?,implementation_level:reconstruct_text(control,header.text(1)?)?},file_name:StepFileName{name:reconstruct_text(control,header.text(2)?)?,timestamp:reconstruct_text(control,header.text(3)?)?,author:header_list(database,"step_author",control,&mut count)?,organization:header_list(database,"step_organization",control,&mut count)?,preprocessor_version:reconstruct_text(control,header.text(4)?)?,originating_system:reconstruct_text(control,header.text(5)?)?,authorization:reconstruct_text(control,header.text(6)?)?},file_schema:StepFileSchema{schemas:header_list(database,"step_schema_identifier",control,&mut count)?}},entities:restored};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,count)?;Ok(result)
    }
}
